package templateengine

import (
	"fmt"
	"path/filepath"
	"reflect"
)

// AcceptBootstrapSnapshot permits exactly one explicitly owned target file to
// change. Source/values/steps/generated bytes and every other target selector
// remain bound to the original approval. The caller must verify live identity
// and persist an atomic receipt before executing another step.
func (p *ExecutionPlan) AcceptBootstrapSnapshot(next *ExecutionPlan, path string) (string, error) {
	if p.Target == nil || !p.Target.Bootstrap || p.Target.Kubernetes == nil || p.Target.Kubernetes.Kubeconfig == "" || p.targetSnapshot == nil || next.targetSnapshot == nil {
		return "", fmt.Errorf("bootstrap target snapshot is unavailable")
	}
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	declared, err := filepath.Abs(p.Target.Kubernetes.Kubeconfig)
	if err != nil || declared != absolute {
		return "", fmt.Errorf("bootstrap target path differs from approved policy")
	}
	before, after := *p, *next
	before.Digest, before.TargetDigest = "", ""
	after.Digest, after.TargetDigest = "", ""
	a, err := digestJSON(before)
	if err != nil {
		return "", err
	}
	b, err := digestJSON(after)
	if err != nil {
		return "", err
	}
	if a != b || p.targetSnapshot.Workspace != next.targetSnapshot.Workspace || !reflect.DeepEqual(p.targetSnapshot.Environment, next.targetSnapshot.Environment) {
		return "", fmt.Errorf("bootstrap changed another approved input")
	}
	oldFiles := map[string]string{}
	newFiles := map[string]string{}
	for key, value := range p.targetSnapshot.Files {
		if key != absolute {
			oldFiles[key] = value
		}
	}
	for key, value := range next.targetSnapshot.Files {
		if key != absolute {
			newFiles[key] = value
		}
	}
	old, oldOK := p.targetSnapshot.Files[absolute]
	observed, newOK := next.targetSnapshot.Files[absolute]
	if !oldOK || !newOK || old != "missing" || observed == "missing" || !reflect.DeepEqual(oldFiles, newFiles) {
		return "", fmt.Errorf("bootstrap changed configuration outside its one absent target file")
	}
	*p = *next
	return observed, nil
}

func (p *ExecutionPlan) TargetFileHash(path string) (string, error) {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	if p.targetSnapshot == nil {
		return "", fmt.Errorf("target snapshot unavailable")
	}
	value, ok := p.targetSnapshot.Files[absolute]
	if !ok {
		return "", fmt.Errorf("target file is not captured")
	}
	return value, nil
}

// BootstrapOriginDigest reconstructs the one original missing-file preview,
// without changing disk bytes. A receipt cannot invent an unrelated origin.
func (p *ExecutionPlan) BootstrapOriginDigest(path string) (string, error) {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	if p.targetSnapshot == nil || p.Target == nil || !p.Target.Bootstrap {
		return "", fmt.Errorf("bootstrap snapshot unavailable")
	}
	if _, ok := p.targetSnapshot.Files[absolute]; !ok {
		return "", fmt.Errorf("bootstrap file is not captured")
	}
	snapshot := *p.targetSnapshot
	snapshot.Files = map[string]string{}
	for key, value := range p.targetSnapshot.Files {
		snapshot.Files[key] = value
	}
	snapshot.Files[absolute] = "missing"
	copyPlan := *p
	copyPlan.Digest = ""
	copyPlan.TargetDigest, err = digestJSON(snapshot)
	if err != nil {
		return "", err
	}
	return digestJSON(copyPlan)
}
